pub fn monte_carlo_estimate(samples: &[(f32, f32)]) -> f32 {
    if samples.is_empty() {
        return 0.0;
    }
    let n = samples.len() as f32;
    let sum: f32 = samples.iter().map(|&(f, p)| f / p).sum();
    sum / n
}

