pub fn schlick_fresnel(cos_theta: f32, r0: f32) -> f32 {
    let c = (1.0 - cos_theta).clamp(0.0, 1.0);
    let c5 = c * c * c * c * c;
    r0 + (1.0 - r0) * c5
}

